class TestSaveCheckpoint:
    """Verify _save_checkpoint writes valid, atomic JSON."""

    def test_writes_valid_json(self, runner):
        data = {"run_name": "test", "completed_prompts": [1, 2, 3], "batch_stats": {}}
        runner._save_checkpoint(data)

        result = json.loads(runner.checkpoint_file.read_text())
        assert result["run_name"] == "test"
        assert result["completed_prompts"] == [1, 2, 3]

    def test_adds_last_updated(self, runner):
        data = {"run_name": "test", "completed_prompts": []}
        runner._save_checkpoint(data)

        result = json.loads(runner.checkpoint_file.read_text())
        assert "last_updated" in result
        assert result["last_updated"] is not None

    def test_overwrites_previous_checkpoint(self, runner):
        runner._save_checkpoint({"run_name": "test", "completed_prompts": [1]})
        runner._save_checkpoint({"run_name": "test", "completed_prompts": [1, 2, 3]})

        result = json.loads(runner.checkpoint_file.read_text())
        assert result["completed_prompts"] == [1, 2, 3]

    def test_with_lock(self, runner):
        lock = Lock()
        data = {"run_name": "test", "completed_prompts": [42]}
        runner._save_checkpoint(data, lock=lock)

        result = json.loads(runner.checkpoint_file.read_text())
        assert result["completed_prompts"] == [42]

    def test_without_lock(self, runner):
        data = {"run_name": "test", "completed_prompts": [99]}
        runner._save_checkpoint(data, lock=None)

        result = json.loads(runner.checkpoint_file.read_text())
        assert result["completed_prompts"] == [99]

    def test_creates_parent_dirs(self, tmp_path):
        runner_deep = BatchRunner.__new__(BatchRunner)
        runner_deep.checkpoint_file = tmp_path / "deep" / "nested" / "checkpoint.json"

        data = {"run_name": "test", "completed_prompts": []}
        runner_deep._save_checkpoint(data)

        assert runner_deep.checkpoint_file.exists()

    def test_no_temp_files_left(self, runner):
        runner._save_checkpoint({"run_name": "test", "completed_prompts": []})

        tmp_files = [f for f in runner.checkpoint_file.parent.iterdir()
                     if ".tmp" in f.name]
        assert len(tmp_files) == 0

class TestResumePreservesProgress:
    """Verify that initializing a run with resume=True loads prior checkpoint."""

    def test_completed_prompts_loaded_from_checkpoint(self, runner):
        # Simulate a prior run that completed prompts 0-4
        prior = {
            "run_name": "test_run",
            "completed_prompts": [0, 1, 2, 3, 4],
            "batch_stats": {"0": {"processed": 5}},
            "last_updated": "2026-01-01T00:00:00",
        }
        runner.checkpoint_file.write_text(json.dumps(prior))

        # Load checkpoint like run() does
        checkpoint_data = runner._load_checkpoint()
        if checkpoint_data.get("run_name") != runner.run_name:
            checkpoint_data = {
                "run_name": runner.run_name,
                "completed_prompts": [],
                "batch_stats": {},
                "last_updated": None,
            }

        completed_set = set(checkpoint_data.get("completed_prompts", []))
        assert completed_set == {0, 1, 2, 3, 4}

    def test_different_run_name_starts_fresh(self, runner):
        prior = {
            "run_name": "different_run",
            "completed_prompts": [0, 1, 2],
            "batch_stats": {},
        }
        runner.checkpoint_file.write_text(json.dumps(prior))

        checkpoint_data = runner._load_checkpoint()
        if checkpoint_data.get("run_name") != runner.run_name:
            checkpoint_data = {
                "run_name": runner.run_name,
                "completed_prompts": [],
                "batch_stats": {},
                "last_updated": None,
            }

        assert checkpoint_data["completed_prompts"] == []
        assert checkpoint_data["run_name"] == "test_run"

class StatusEvent:
    """A single status event for SSE streaming."""

    def __init__(self, job_id: str, event_type: str, data: Dict[str, Any]):
        self.job_id = job_id
        self.event_type = event_type
        self.data = data
        self.timestamp = datetime.utcnow().isoformat()

    def to_sse(self) -> str:
        """Format as Server-Sent Event string."""
        payload = {
            "job_id": self.job_id,
            "event": self.event_type,
            "data": self.data,
            "timestamp": self.timestamp,
        }
        return f"data: {json.dumps(payload)}\n\n"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "job_id": self.job_id,
            "event": self.event_type,
            "data": self.data,
            "timestamp": self.timestamp,
        }

class JobTracker:
    """Thread-safe job status tracker with event history and SSE support."""

    def __init__(self, max_events_per_job: int = 500):
        self._lock = threading.Lock()
        self._jobs: Dict[str, Job] = {}
        self._statuses: Dict[str, JobStatus] = {}
        self._events: Dict[str, List[StatusEvent]] = defaultdict(list)
        self._subscribers: Dict[str, List[Callable[[StatusEvent], None]]] = defaultdict(list)
        self._max_events = max_events_per_job

    def register_job(self, job: Job) -> None:
        """Register a new job for tracking."""
        with self._lock:
            self._jobs[job.id] = job
            self._statuses[job.id] = JobStatus(
                job_id=job.id,
                state=job.state,
                steps_total=len(job.workflow.steps) if job.workflow else 0,
            )
        self._emit(job.id, "job.registered", {"goal": job.goal, "state": job.state.value})

    def update_state(self, job_id: str, state: JobState) -> None:
        """Update the overall job state."""
        with self._lock:
            if job_id in self._jobs:
                self._jobs[job_id].state = state
                self._jobs[job_id].updated_at = datetime.utcnow()
            if job_id in self._statuses:
                self._statuses[job_id].state = state
        self._emit(job_id, "job.state_changed", {"state": state.value})

    def update_step(self, job_id: str, step_id: str, event: str, result: Optional[WorkerResult] = None) -> None:
        """Update a specific step's status."""
        with self._lock:
            status = self._statuses.get(job_id)
            if status:
                status.current_step = step_id
                if result:
                    status.step_results.append(result)
                    if result.status.value == "completed":
                        status.steps_completed += 1
                    status.total_tokens += result.tokens_used

        data: Dict[str, Any] = {"step_id": step_id, "event": event}
        if result:
            data["agent_name"] = result.agent_name
            data["status"] = result.status.value
            data["duration"] = result.duration_seconds
        self._emit(job_id, f"step.{event}", data)

    def complete_job(self, job_id: str, final_output: str, state: JobState = JobState.COMPLETED) -> None:
        """Mark a job as completed with final output."""
        with self._lock:
            if job_id in self._jobs:
                self._jobs[job_id].state = state
                self._jobs[job_id].completed_at = datetime.utcnow()
            if job_id in self._statuses:
                self._statuses[job_id].state = state
                self._statuses[job_id].final_output = final_output
        self._emit(job_id, "job.completed", {"state": state.value, "output_length": len(final_output)})

    def get_status(self, job_id: str) -> Optional[JobStatus]:
        """Get the current status of a job."""
        with self._lock:
            return self._statuses.get(job_id)

    def get_job(self, job_id: str) -> Optional[Job]:
        """Get a job by ID."""
        with self._lock:
            return self._jobs.get(job_id)

    def list_jobs(self, state: Optional[JobState] = None) -> List[Job]:
        """List all tracked jobs, optionally filtered by state."""
        with self._lock:
            jobs = list(self._jobs.values())
        if state:
            jobs = [j for j in jobs if j.state == state]
        return sorted(jobs, key=lambda j: j.created_at, reverse=True)

    def get_events(self, job_id: str, since: int = 0) -> List[StatusEvent]:
        """Get events for a job since a given index."""
        with self._lock:
            events = self._events.get(job_id, [])
            return events[since:]

    def subscribe(self, job_id: str, callback: Callable[[StatusEvent], None]) -> Callable:
        """Subscribe to events for a job. Returns an unsubscribe function."""
        with self._lock:
            self._subscribers[job_id].append(callback)

        def unsubscribe():
            with self._lock:
                try:
                    self._subscribers[job_id].remove(callback)
                except ValueError:
                    pass

        return unsubscribe

    def _emit(self, job_id: str, event_type: str, data: Dict[str, Any]) -> None:
        """Emit an event to all subscribers and store in history."""
        event = StatusEvent(job_id, event_type, data)

        with self._lock:
            events = self._events[job_id]
            events.append(event)
            if len(events) > self._max_events:
                self._events[job_id] = events[-self._max_events:]
            subscribers = list(self._subscribers.get(job_id, []))

        for callback in subscribers:
            try:
                callback(event)
            except Exception as e:
                logger.warning("Event subscriber error: %s", e)

class AgentRoster:
    """Registry of all available agent definitions loaded from agency_roster/."""

    def __init__(self) -> None:
        self._agents: Dict[str, AgentDefinition] = {}  # keyed by normalized name
        self._by_division: Dict[str, List[AgentDefinition]] = {}

    @staticmethod
    def _normalize_name(name: str) -> str:
        """Normalize agent name for lookup (lowercase, stripped)."""
        return name.lower().strip()

    def load(self, roster_dir: Optional[Path] = None) -> int:
        """Load all agent .md files from roster_dir. Returns count loaded."""
        roster_dir = Path(roster_dir or _DEFAULT_ROSTER_DIR)
        if not roster_dir.is_dir():
            logger.warning("Roster directory not found: %s", roster_dir)
            return 0

        count = 0
        for md_file in sorted(roster_dir.rglob("*.md")):
            # Skip _defaults.yaml and other non-agent files
            if md_file.name.startswith("_"):
                continue
            agent = _parse_agent_file(md_file)
            if agent:
                key = self._normalize_name(agent.name)
                self._agents[key] = agent
                self._by_division.setdefault(agent.division, []).append(agent)
                count += 1
                logger.debug("Loaded agent: %s (%s)", agent.name, agent.division)

        logger.info("Loaded %d agents from %s", count, roster_dir)
        return count

    def get_agent(self, name: str) -> Optional[AgentDefinition]:
        """Get an agent by exact name (case-insensitive)."""
        return self._agents.get(self._normalize_name(name))

    def search(self, query: str, top_k: int = 10) -> List[AgentDefinition]:
        """Search agents by relevance to a query string."""
        scored = [
            (agent, agent.match_score(query))
            for agent in self._agents.values()
        ]
        scored.sort(key=lambda x: x[1], reverse=True)
        return [agent for agent, score in scored[:top_k] if score > 0.0]

    def list_division(self, division: str) -> List[AgentDefinition]:
        """List all agents in a specific division."""
        return self._by_division.get(division, [])

    def list_all(self) -> List[AgentDefinition]:
        """List all loaded agents."""
        return list(self._agents.values())

    def list_divisions(self) -> List[str]:
        """List all division names."""
        return sorted(self._by_division.keys())

    def get_roster_summary(self) -> str:
        """Generate a compact text summary for the Manager's system prompt context."""
        lines = []
        for division in sorted(self._by_division.keys()):
            agents = self._by_division[division]
            div_display = division.replace("_", " ").title()
            lines.append(f"\n## {div_display} Division ({len(agents)} agents)")
            for agent in agents:
                use = f" | Use: {agent.use_case}" if agent.use_case else ""
                lines.append(f"  - {agent.emoji} {agent.name}: {agent.specialty}{use}")
        return "\n".join(lines)

    def __len__(self) -> int:
        return len(self._agents)

    def __contains__(self, name: str) -> bool:
        return self._normalize_name(name) in self._agents

