            content=(
                'def run():\n'
                '    cmd = "echo a | sed s/a/b/"\n'
                '    result = 1\n'
                '    return result'
            ),
            error=None,
        )

    def write_file(self, path, content):
        self.written = content
        return SimpleNamespace(error=None)

